import {configSection,today,round,quoteTotals} from '../core/business.js?v=20261102-v6a';
// Functions receive shared services and state through an explicit application context.
export function install(ctx){
function quoteTable(list){return list.length?`<div class="table-wrap"><table><thead><tr><th>Orçamento</th><th>Cliente</th><th>Emissão</th><th>Total</th><th>Etapa</th><th></th></tr></thead><tbody>${list.map(q=>`<tr><td><strong>#${String(q.number).padStart(4,'0')}</strong></td><td>${ctx.esc(q.client_snapshot.name)}</td><td>${ctx.date(q.created_at)}</td><td class="nowrap">${ctx.money(q.total)}</td><td>${ctx.stageBadge?ctx.stageBadge(q):ctx.esc(q.stage||"Rascunho")}</td><td><button class="secondary small" data-view="${q.id}">Abrir ${ctx.icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:ctx.empty('Seu próximo pedido começa aqui.','Crie um orçamento para acompanhar os valores e compartilhar com seu cliente.')}

function calc(cost,method,pct){if(!Number.isFinite(pct)||pct<0||(method==='margin'&&pct>=100))return NaN;return Math.round((method==='markup'?cost*(1+pct/100):cost/(1-pct/100))*100)/100}

function quoteForm(){
 const budget=configSection(ctx.settings,'budget'),meta=ctx.quoteDraftMeta||{};
 if(!ctx.clients.length||!ctx.products.length){ctx.shell(`${ctx.head('Novo orçamento','Cadastre o que faltar sem sair desta tela.')}<section class="panel">${ctx.empty('Prepare a base da sua proposta.','O cadastro rápido abre uma janela e seleciona o novo registro.')}<div class="form-actions">${ctx.can('clients','create')?'<button class="secondary" id="quick-empty-client">Cadastrar cliente</button>':''}${ctx.can('products','create')?'<button class="primary" id="quick-empty-product">Cadastrar produto</button>':''}</div></section>`);ctx.$('#quick-empty-client')?.addEventListener('click',()=>ctx.quickRecordDialog('clients',c=>{ctx.quoteDraftMeta={...meta,client:c.id};quoteForm()}));ctx.$('#quick-empty-product')?.addEventListener('click',()=>ctx.quickRecordDialog('products',()=>quoteForm()));return}
 if(!ctx.draft.length)ctx.draft=[{product_id:ctx.products[0].id,quantity:1,details:'',custom_unit_price:null,untouched:true}];
 const validity=new Date(today()+'T12:00:00Z');validity.setUTCDate(validity.getUTCDate()+Number(budget.validity_days));
 ctx.shell(`${ctx.head(meta.revision_of?'Revisar orçamento':'Novo orçamento','Preço sugerido, liberdade para negociar e margem calculada automaticamente.')}<form id="quote-form">${meta.revision_of?'<p class="note">Esta revisão gera uma nova proposta. A emissão anterior e suas parcelas permanecem no histórico.</p>':''}<div class="quote-layout"><div><section class="panel"><div class="panelhead"><h2>01 · Dados da proposta</h2>${ctx.can('clients','create')?'<button type="button" class="secondary small" id="quick-client">Cadastrar cliente</button>':''}</div><div class="panelbody grid2"><label class="field">Cliente<select id="client" name="client" required>${ctx.clients.map(c=>`<option value="${c.id}" ${meta.client===c.id?'selected':''}>${ctx.esc(c.name)} · ${c.kind}</option>`).join('')}</select></label>${ctx.field('Válido até','valid','date',meta.valid||validity.toISOString().slice(0,10),'required')}${ctx.field('Entrega prevista','delivery_date','date',meta.delivery_date||'')}${ctx.field('Entrada acordada (%)','entry_percentage','number',meta.entry_percentage??budget.deposit_percentage,'required min="0" max="100" step="0.01"')}<label class="field">Personalização<select name="technique">${configSection(ctx.settings,'production').techniques.map(t=>`<option ${meta.technique===t?'selected':''}>${ctx.esc(t)}</option>`).join('')}</select></label></div></section><section class="panel"><div class="panelhead"><h2>02 · Itens e preços</h2>${ctx.can('products','create')?'<button type="button" class="secondary small" id="quick-product">Cadastrar produto</button>':''}</div><div class="panelbody"><div id="items"></div><button type="button" class="secondary small" id="add-item">${ctx.icon('plus')} Adicionar item</button><p class="note">O valor unitário pode ser alterado. A sugestão permanece visível e pode ser restaurada em cada item.</p></div></section><section class="panel"><div class="panelhead"><h2>03 · Observações e personalização</h2></div><div class="panelbody"><label class="field">Condições de pagamento, prazo e observações<textarea name="notes" maxlength="10000">${ctx.esc(meta.notes??ctx.settings.conditions??'')}</textarea></label></div></section></div><aside class="panel quote-summary"><div class="panelhead"><h2>Resumo da proposta</h2></div><div class="panelbody"><label class="field">Método do preço sugerido<select id="method" name="method"><option value="markup">Acréscimo sobre o custo</option><option value="margin">Margem sobre a venda</option></select></label>${ctx.field('Percentual sugerido (%)','percentage','number',meta.percentage??ctx.settings.percentage??30,'id="percentage" required min="0" max="9999" step="0.01"')}<p id="method-note" class="note"></p><div class="divider"></div><span class="muted">Valor total</span><div class="total" id="total"></div><div class="profit-preview"><div>Custo dos itens <strong id="quote-cost"></strong></div><div>Lucro bruto estimado <strong id="quote-profit"></strong></div><div>Margem bruta estimada <strong id="quote-margin"></strong></div></div><p class="muted helper">A margem usa o custo cadastrado dos produtos. Outros gastos da empresa dependem dos lançamentos financeiros.</p><p id="quote-error" role="alert"></p><button type="submit" class="primary wide">Salvar ${meta.revision_of?'revisão':'orçamento'}</button></div></aside></div></form>`);
 const form=ctx.$('#quote-form');ctx.$('#method').value=meta.method||ctx.settings.method||'markup';
 if(!ctx.can('quotes','price')){ctx.$('#method').disabled=true;ctx.$('#percentage').readOnly=true;}
 function remember(){ctx.quoteDraftMeta={...ctx.quoteDraftMeta,...Object.fromEntries(new FormData(form)),method:ctx.$('#method').value,percentage:ctx.$('#percentage').value};}
 function update(){const method=ctx.$('#method').value,pct=Number(ctx.$('#percentage').value),totals=quoteTotals(ctx.draft,ctx.products,method,pct);ctx.$('#percentage').max=method==='margin'?'99.99':'9999';ctx.$('#method-note').textContent='O percentual altera a sugestão. Preços digitados manualmente permanecem como você definiu.';totals.lines.forEach((line,i)=>{const input=ctx.$('#unit-'+i);if(input&&ctx.draft[i].custom_unit_price==null)input.value=Number.isFinite(line.suggested)?line.suggested:'';const hint=ctx.$('#suggested-'+i);if(hint)hint.textContent='Sugerido: '+(Number.isFinite(line.suggested)?ctx.money(line.suggested):'percentual inválido');ctx.$('#reset-'+i)?.classList.toggle('muted',!line.overridden)});ctx.$('#total').textContent=Number.isFinite(totals.sales)?ctx.money(totals.sales):'Preço inválido';ctx.$('#quote-cost').textContent=ctx.money(totals.cost);ctx.$('#quote-profit').textContent=ctx.money(totals.profit);ctx.$('#quote-margin').textContent=totals.margin===null?'—':totals.margin.toLocaleString('pt-BR',{maximumFractionDigits:2,minimumFractionDigits:2})+'%';ctx.$('#quote-margin').className=totals.profit<0?'negative-text':'positive-text';remember();}
 function rows(){const suggested=quoteTotals(ctx.draft,ctx.products,ctx.$('#method').value,Number(ctx.$('#percentage').value));ctx.$('#items').innerHTML=ctx.draft.map((it,i)=>`<div class="quote-row editable-price"><label class="field">Produto<select data-item="${i}" data-key="product_id">${ctx.products.map(p=>`<option value="${p.id}" ${it.product_id===p.id?'selected':''}>${ctx.esc(p.name)}${p.sku?' · '+ctx.esc(p.sku):''}</option>`).join('')}</select></label><label class="field">Qtd.<input type="number" data-item="${i}" data-key="quantity" aria-label="Quantidade item ${i+1}" value="${it.quantity}" required min="1" max="100000" step="1"></label><label class="field">Unitário (R$)<input id="unit-${i}" type="number" data-item="${i}" data-key="custom_unit_price" aria-label="Preço unitário item ${i+1}" ${ctx.can('quotes','price')?'':'readonly'} value="${it.custom_unit_price??suggested.lines[i].suggested}" required min="0" max="9999999999" step="0.01"><small id="suggested-${i}"></small><button class="ghost small" type="button" id="reset-${i}" data-reset-price="${i}">Usar sugerido</button></label><button class="ghost small" type="button" data-remove="${i}" aria-label="Remover item ${i+1}">${ctx.icon('x')}</button><textarea data-item="${i}" data-key="details" aria-label="Personalização item ${i+1}" maxlength="5000" placeholder="Arte, tamanhos, nomes e números…">${ctx.esc(it.details)}</textarea></div>`).join('');document.querySelectorAll('[data-item]').forEach(el=>el.oninput=()=>{const item=ctx.draft[el.dataset.item];item[el.dataset.key]=el.value;item.untouched=false;if(el.dataset.key==='product_id')item.custom_unit_price=null;update()});document.querySelectorAll('[data-reset-price]').forEach(el=>el.onclick=()=>{ctx.draft[el.dataset.resetPrice].custom_unit_price=null;rows()});document.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{if(ctx.draft.length===1)return ctx.toast('Mantenha ao menos um item.');ctx.draft.splice(Number(el.dataset.remove),1);rows()});update();}
 rows();form.addEventListener('input',remember);form.addEventListener('change',remember);ctx.$('#method').onchange=update;ctx.$('#percentage').oninput=update;
 ctx.$('#add-item').onclick=()=>{if(ctx.draft.length>=100)return ctx.toast('Limite de 100 itens.');ctx.draft.push({product_id:ctx.products[0].id,quantity:1,details:'',custom_unit_price:null,untouched:true});rows()};
 ctx.$('#quick-client')?.addEventListener('click',()=>{remember();ctx.quickRecordDialog('clients',c=>{ctx.quoteDraftMeta.client=c.id;quoteForm()})});
 ctx.$('#quick-product')?.addEventListener('click',()=>{remember();ctx.quickRecordDialog('products',p=>{const empty=ctx.draft.find(it=>it.untouched);if(empty){empty.product_id=p.id;empty.custom_unit_price=null;empty.untouched=false}else if(ctx.draft.length<100)ctx.draft.push({product_id:p.id,quantity:1,details:'',custom_unit_price:null});quoteForm()})});
 form.onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{remember();const f=new FormData(form),id=await ctx.rpc('create_quote_v3',{p_client:f.get('client'),p_method:ctx.$('#method').value,p_percentage:Number(ctx.$('#percentage').value),p_valid_until:f.get('valid'),p_notes:f.get('notes'),p_meta:{revision_of:ctx.quoteDraftMeta.revision_of||null,delivery_date:f.get('delivery_date'),entry_percentage:Number(f.get('entry_percentage')),technique:f.get('technique')},p_items:ctx.draft.map(it=>({product_id:it.product_id,quantity:Number(it.quantity),details:it.details,custom_unit_price:it.custom_unit_price==null?null:Number(it.custom_unit_price)}))});ctx.draft=[];ctx.quoteDraftMeta=null;await ctx.load();await ctx.openQuote(id);ctx.toast('Proposta salva com os preços definidos.')}catch(err){ctx.$('#quote-error').textContent=err.message;ctx.$('#quote-error').className='error';e.submitter.disabled=false}};
}
async function reviseQuote(id){try{const [qs,items]=await Promise.all([ctx.api('/rest/v1/quotes?id=eq.'+id+'&select=*'),ctx.api('/rest/v1/quote_items?quote_id=eq.'+id+'&select=*')]),q=qs[0];if(!q)throw Error('Orçamento indisponível.');ctx.draft=items.map(it=>({product_id:it.product_id,quantity:it.quantity,details:it.details,custom_unit_price:Number(it.unit_price)}));ctx.quoteDraftMeta={client:q.client_id,method:q.method,percentage:q.percentage,notes:q.notes,entry_percentage:q.entry_percentage,delivery_date:q.delivery_date,technique:q.production?.technique,revision_of:q.id};ctx.render('quote')}catch(e){ctx.toast(e.message)}}

async function openQuote(id){try{const q=ctx.quotes.find(q=>q.id===id);if(!q)throw Error('Orçamento não encontrado.');const [details,items]=await Promise.all([ctx.api('/rest/v1/quotes?id=eq.'+id+'&select=*'),ctx.api('/rest/v1/quote_items?quote_id=eq.'+id+'&select=*&order=id')]);if(!details[0])throw Error('Orçamento indisponível.');ctx.viewQuote={...details[0],items};ctx.render('view')}catch(e){ctx.toast(e.message)}}

function printView(){const q=ctx.viewQuote,c=q.client_snapshot,company=q.company_snapshot||{},budget=company.budget||{},entry=round(Number(q.total)*Number(q.entry_percentage??50)/100),internalCost=round(q.items.reduce((n,it)=>n+Number(it.cost_snapshot)*Number(it.quantity),0)),internalProfit=round(Number(q.total)-internalCost),internalMargin=Number(q.total)>0?round(internalProfit/Number(q.total)*100):null;ctx.shell(`${ctx.head('Orçamento #'+String(q.number).padStart(4,'0'),'Proposta salva. Os preços deste documento preservam o histórico.')}<div class="form-actions" style="border:0;padding:0;margin-bottom:25px"><button class="secondary" data-action="quotes">Voltar para orçamentos</button>${ctx.can('workflow')?'<button class="secondary" id="quote-workflow">Ver pedido / produção</button>':''}${ctx.can('finance','create')?'<button class="secondary" id="quote-receivables">Gerar entrada e saldo</button>':''}${ctx.can('quotes','create')&&ctx.can('quotes','price')?'<button class="secondary" id="revise-quote">Revisar preços / proposta</button>':''}${ctx.can('receipts','view')?'<button class="secondary" id="quote-receipts">Recibos</button>':''}${ctx.can('quotes','print')?'<button class="primary" id="quote-share-pdf">Compartilhar PDF</button>':''}<button class="secondary" id="print">${ctx.icon('print')} Imprimir / Salvar PDF</button></div>${ctx.can('quotes','price')?`<section class="quote-internal-summary panel panelbody"><strong>Análise interna da proposta</strong><div class="profit-preview"><div>Custo dos itens <strong>${ctx.money(internalCost)}</strong></div><div>Lucro bruto estimado <strong>${ctx.money(internalProfit)}</strong></div><div>Margem bruta estimada <strong>${internalMargin===null?'—':internalMargin.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})+'%'}</strong></div></div><p class="muted helper">Esta análise não aparece no PDF enviado ao cliente.</p></section>`:''}<article class="quote-print">${['cancelled','suspended'].includes(q.stage)?`<div class="quote-status-note">${q.stage==='cancelled'?'PROPOSTA CANCELADA':'PROPOSTA SUSPENSA'} · Confirme a situação do pedido antes de utilizá-la.</div>`:''}<header><div ${budget.show_company===false?'hidden':''}><div class="brand ${company.logo?'custom-brand':'document-brand'}"><img src="${ctx.esc(company.logo||'logo-document.png')}" alt="${ctx.esc(company.company||'Avelon Têxtil')}"></div><p>${ctx.esc(company.company||'AVELON TÊXTIL · Confecções')}<br>${ctx.esc(company.contact||'Onde sua imaginação ganha forma.')}</p></div><div><h1>ORÇAMENTO</h1><p><strong>Nº ${String(q.number).padStart(4,'0')}</strong><br>Emissão: ${ctx.date(q.created_at)}<br>Validade: ${ctx.date(q.valid_until)}</p></div></header><div class="eyebrow">Preparado para</div><h2 style="font:700 20px Manrope">${ctx.esc(c.name)}</h2><p>${ctx.esc(c.kind)}${c.document?' · '+ctx.esc(c.document):''}<br>${ctx.esc(c.phone)}${c.email?' · '+ctx.esc(c.email):''}<br>${ctx.esc(c.address)}</p><div class="table-wrap"><table><thead><tr><th>Produto e personalização</th><th>Qtd.</th><th>Unitário</th><th>Subtotal</th></tr></thead><tbody>${q.items.map(it=>`<tr><td><strong>${ctx.esc(it.description)}</strong><div class="details">${ctx.esc(it.details)}</div></td><td>${it.quantity}</td><td class="nowrap">${ctx.money(it.unit_price)}</td><td class="nowrap">${ctx.money(it.quantity*it.unit_price)}</td></tr>`).join('')}</tbody></table></div><div class="print-total">Valor total <strong>${ctx.money(q.total)}</strong></div>${q.entry_percentage!==undefined?`<p><strong>Entrada acordada (${q.entry_percentage}%):</strong> ${ctx.money(entry)} · <strong>Saldo:</strong> ${ctx.money(round(q.total-entry))}<br>${budget.payment_methods?'Pagamento: '+ctx.esc(budget.payment_methods):''}${budget.production_days?'<br>Prazo estimado de produção: '+budget.production_days+' dias após confirmação, entrada e aprovação da arte.':''}${q.delivery_date?'<br>Entrega prevista: '+ctx.date(q.delivery_date):''}</p>`:''}${q.notes?`<div class="divider"></div><div class="eyebrow">Condições e observações</div><p>${ctx.esc(q.notes)}</p>`:''}${budget.show_notes!==false&&budget.important_notes?`<section class="budget-notes"><p>${ctx.esc(budget.important_notes)}</p></section>`:''}${budget.show_signature!==false&&company.signature?`<div class="document-signature"><img class="${company.signature_invert?'invert-signature':''}" src="${ctx.esc(company.signature)}" alt="Assinatura de ${ctx.esc(company.signature_name||'responsável')}"><p>${ctx.esc(company.signature_name)}<br>${company.city||budget.city?ctx.esc(company.city||budget.city)+', ':''}${ctx.date(q.created_at)}</p></div>`:''}<div class="divider"></div><p class="muted">Obrigado por escolher a Avelon Têxtil.<br>Esta proposta é válida até ${ctx.date(q.valid_until)}. Produção sujeita à confirmação das condições acordadas.</p></article>`);ctx.$('#quote-share-pdf')?.addEventListener('click',e=>ctx.shareDocument({filename:'Avelon-Orcamento-'+String(q.number).padStart(4,'0')+'.pdf',title:'Orçamento Avelon #'+q.number,button:e.currentTarget,authorize:async()=>{const fresh=await ctx.rpc('quote_print_data',{p_quote:q.id});ctx.viewQuote={...fresh.quote,items:fresh.items||[]};ctx.printView()}}));ctx.$('#revise-quote')?.addEventListener('click',()=>reviseQuote(q.id));ctx.$('#quote-receipts')?.addEventListener('click',()=>ctx.receiptListDialog(q.id));ctx.$('#quote-workflow')?.addEventListener('click',()=>ctx.orderDialog(q.id));ctx.$('#quote-receivables')?.addEventListener('click',()=>ctx.receivableDialog(q.id));if(ctx.$('#print'))ctx.$('#print').onclick=async()=>{try{await ctx.api('/rest/v1/rpc/quote_print_data',{method:'POST',body:{p_quote:q.id}});window.print()}catch(e){ctx.toast(e.message)}}}
function quotesPage(){ctx.shell(`${ctx.head('Orçamentos','Propostas, pedidos e histórico dos documentos.','quote','Novo orçamento')}<div class="toolbar"><input type="search" id="quote-search" placeholder="Buscar cliente ou número…" aria-label="Buscar orçamento"></div><section class="panel" id="quote-list">${quoteTable(ctx.quotes)}</section>`);ctx.$('#quote-search').oninput=e=>{const s=e.target.value.toLowerCase();ctx.$('#quote-list').innerHTML=quoteTable(ctx.quotes.filter(q=>(q.number+' '+q.client_snapshot.name).toLowerCase().includes(s)));document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>openQuote(b.dataset.view))}}
Object.assign(ctx,{quoteTable,calc,quoteForm,openQuote,printView,quotesPage,reviseQuote});
}
